/* Pixel Quiz – cohesive 4-color palette */
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #f0f0f0;
  --muted: #a0a0b0;
  --pixel: 4px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
  background-image:
    linear-gradient(45deg, #1f1f3a 25%, transparent 25%),
    linear-gradient(-45deg, #1f1f3a 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #1f1f3a 75%),
    linear-gradient(-45deg, transparent 75%, #1f1f3a 75%);
  background-size: 32px 32px;
  background-position: 0 0, 0 16px, 16px -16px, -16px 0;
}

.card {
  background: var(--card);
  border: var(--pixel) solid var(--accent);
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 20px;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
}

.pixel-text {
  font-size: 1.5rem;
  text-align: center;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 #000;
}

.question {
  font-size: 1.75rem;
  text-align: center;
  min-height: 2.5rem;
  font-weight: 700;
  letter-spacing: 1px;
}

.answers {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.score-line {
  text-align: center;
  font-size: 1.1rem;
  color: var(--muted);
}

#score { color: var(--accent); font-weight: 700; }

.btn {
  font: inherit;
  cursor: pointer;
  border: var(--pixel) solid var(--accent);
  background: var(--bg);
  color: var(--text);
  padding: 14px 8px;
  font-weight: 700;
  letter-spacing: 1px;
  transition: transform 0.05s, background 0.15s;
  min-height: 48px;
}

.btn:hover { background: #2a2a4a; }
.btn:focus-visible { outline: 3px solid var(--text); outline-offset: 2px; }
.btn:active { transform: translate(2px, 2px); }

.btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

.answer.correct { background: #2e7d32; border-color: #2e7d32; }
.answer.wrong { background: #b71c1c; border-color: #b71c1c; }

.controls { display: flex; gap: 12px; }
.controls .btn { flex: 1; }

@media (max-width: 360px) {
  .card { padding: 20px 14px; }
  .question { font-size: 1.4rem; }
  .btn { font-size: 1rem; }
}

const questionEl = document.getElementById('question');
const scoreEl = document.getElementById('score');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

let current = 0;
let score = 0;
let locked = false;
let finished = false;

function render() {
  if (finished) {
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
    nextBtn.disabled = true;
    return;
  }
  const q = questions[current];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.disabled = locked;
  answerB.disabled = locked;
  answerA.classList.remove('correct', 'wrong');
  answerB.classList.remove('correct', 'wrong');
  nextBtn.disabled = !locked;
}

function updateScore() {
  scoreEl.textContent = String(score);
}

function handleAnswer(choice) {
  if (locked || finished) return;
  locked = true;
  const q = questions[current];
  const btn = choice === 'a' ? answerA : answerB;
  if (q.correct === choice) {
    score += 1;
    btn.classList.add('correct');
  } else {
    btn.classList.add('wrong');
    const correctBtn = q.correct === 'a' ? answerA : answerB;
    correctBtn.classList.add('correct');
  }
  updateScore();
  answerA.disabled = true;
  answerB.disabled = true;
  nextBtn.disabled = false;
}

answerA.addEventListener('click', () => handleAnswer('a'));
answerB.addEventListener('click', () => handleAnswer('b'));

nextBtn.addEventListener('click', () => {
  if (!locked || finished) return;
  if (current === 0) {
    current = 1;
    locked = false;
    render();
  } else {
    finished = true;
    render();
  }
});

restartBtn.addEventListener('click', () => {
  current = 0;
  score = 0;
  locked = false;
  finished = false;
  updateScore();
  render();
});

render();
updateScore();
